<?php// app/Http/Controllers/Logistique/LogistiqueController.phpnamespace App\Http\Controllers\Client\CommandeClient;use App\Http\Controllers\Controller;use App\Models\CommandeClient;use App\Models\LigneCommande;use App\Models\Succursale;use App\Models\StockSuccursale;use App\Models\Utilisateur;use App\Models\MouvementStock;use App\Models\Produit;use App\Services\CommandeService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Log;class LogistiqueCommandeController extends Controller{    protected CommandeService $commandeService;    public function __construct(CommandeService $commandeService)    {        $this->commandeService = $commandeService;    }    /**     * =============================================     * TABLEAU DE BORD LOGISTICIEN     * =============================================     */        /**     * Dashboard du logisticien     */    public function dashboard(Request $request){    try {        $user = auth()->user();        if (!$user) {            return response()->json([                'success' => false,                'message' => 'Utilisateur non authentifié.'            ], 401);        }        // Si l'utilisateur est chef d'agence, filtrer par sa succursale        $isChefAgence = $user->isChefAgence();        $succursaleId = $user->succursale_id;        $query = CommandeClient::query();        $queryEnAttente = CommandeClient::query();        $queryEnCours = CommandeClient::query();        if ($isChefAgence && $succursaleId) {            $query->where('succursale_assignee_id', $succursaleId);            $queryEnAttente->where('succursale_assignee_id', $succursaleId);            $queryEnCours->where('succursale_assignee_id', $succursaleId);        }        $statuts = [            'EN_ATTENTE_LOGISTIQUE' => (clone $query)->where('statut', 'EN_ATTENTE_LOGISTIQUE')->count(),            'ASSIGNEE' => (clone $query)->where('statut', 'ASSIGNEE')->count(),            'EN_PREPARATION' => (clone $query)->where('statut', 'EN_PREPARATION')->count(),            'PRETE' => (clone $query)->where('statut', 'PRETE')->count(),            'EN_LIVRAISON' => (clone $query)->where('statut', 'EN_LIVRAISON')->count(),        ];        // Commandes en attente d'assignation        $enAttente = (clone $queryEnAttente)->enAttenteAssignation()            ->with(['client', 'lignes.produit'])            ->latest()            ->limit(10)            ->get();        // Commandes en cours        $enCours = (clone $queryEnCours)->whereIn('statut', ['ASSIGNEE', 'EN_PREPARATION', 'PRETE', 'EN_LIVRAISON'])            ->with(['client', 'succursaleAssignee', 'lignes.produit'])            ->latest()            ->limit(10)            ->get();        // ✅ CORRECTION ICI : Utiliser withCount avec une relation directe        $succursalesQuery = Succursale::where('est_active', true);                if ($isChefAgence && $succursaleId) {            $succursalesQuery->where('id', $succursaleId);        }        $succursales = $succursalesQuery->get(['id', 'nom', 'code', 'ville']);        // Calculer la charge de travail manuellement        $succursalesWithCharge = $succursales->map(function ($succursale) {            $charge = CommandeClient::where('succursale_assignee_id', $succursale->id)                ->whereIn('statut', ['ASSIGNEE', 'EN_PREPARATION', 'PRETE'])                ->count();            return [                'id' => $succursale->id,                'nom' => $succursale->nom,                'code' => $succursale->code,                'ville' => $succursale->ville,                'commandes_en_cours' => $charge,            ];        });        return response()->json([            'success' => true,            'data' => [                'statistiques' => $statuts,                'en_attente_assignation' => $enAttente,                'commandes_en_cours' => $enCours,                'succursales' => $succursalesWithCharge,                'total_assignees' => array_sum($statuts) - $statuts['EN_ATTENTE_LOGISTIQUE'],                'user' => [                    'id' => $user->id,                    'nom' => $user->nom_complet,                    'role' => $user->role?->nom_role,                    'succursale' => $user->succursale?->nom,                    'est_chef_agence' => $isChefAgence,                ]            ]        ]);    } catch (\Throwable $e) {        Log::error('Erreur dashboard logistique: ' . $e->getMessage());        return response()->json([            'success' => false,            'message' => $e->getMessage()        ], 500);    }}    /**     * =============================================     * GESTION DES COMMANDES     * =============================================     */    /**     * Liste des commandes avec filtres logistiques     */    public function index(Request $request)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $isChefAgence = $user->isChefAgence();            $succursaleId = $user->succursale_id;            $query = CommandeClient::with([                'client',                'lignes.produit',                'livraison',                'succursaleAssignee'            ]);            // Filtrer par succursale si chef d'agence            if ($isChefAgence && $succursaleId) {                $query->where('succursale_assignee_id', $succursaleId);            }            // Filtres            if ($request->filled('statut')) {                $query->where('statut', $request->statut);            }            if ($request->filled('statut_logistique')) {                $query->where('statut_logistique', $request->statut_logistique);            }            if ($request->filled('succursale_id')) {                if (!$isChefAgence || $succursaleId == $request->succursale_id) {                    $query->where('succursale_assignee_id', $request->succursale_id);                }            }            if ($request->filled('client_id')) {                $query->where('client_id', $request->client_id);            }            if ($request->filled('reference')) {                $query->where('reference', 'LIKE', '%' . $request->reference . '%');            }            if ($request->filled('date_debut')) {                $query->whereDate('created_at', '>=', $request->date_debut);            }            if ($request->filled('date_fin')) {                $query->whereDate('created_at', '<=', $request->date_fin);            }            // Tri            $sortField = $request->get('sort_by', 'created_at');            $sortDirection = $request->get('sort_direction', 'desc');            $query->orderBy($sortField, $sortDirection);            $commandes = $query->paginate($request->get('per_page', 20));            return response()->json([                'success' => true,                'data' => $commandes            ]);        } catch (\Throwable $e) {            Log::error('Erreur index logistique: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 500);        }    }    /**     * Détails d'une commande pour le logisticien     */    public function show($id)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $commande = CommandeClient::with([                'client',                'lignes.produit',                'livraison',                'succursaleAssignee',                'assignePar'            ])->findOrFail($id);            // Vérifier les permissions            if ($user->isChefAgence() && $user->succursale_id) {                if ($commande->succursale_assignee_id && $commande->succursale_assignee_id != $user->succursale_id) {                    return response()->json([                        'success' => false,                        'message' => 'Vous n\'avez pas accès à cette commande.'                    ], 403);                }            }            // Vérifier le stock disponible par succursale pour cette commande            $stockParSuccursale = [];            foreach ($commande->lignes as $ligne) {                $stocks = StockSuccursale::where('produit_id', $ligne->produit_id)                    ->with('succursale')                    ->where('quantite_disponible', '>=', $ligne->quantite)                    ->get();                $stockParSuccursale[$ligne->produit_id] = [                    'produit' => $ligne->produit->nom,                    'quantite_demandee' => $ligne->quantite,                    'succursales' => $stocks->map(function ($stock) {                        return [                            'id' => $stock->succursale_id,                            'nom' => $stock->succursale->nom,                            'disponible' => $stock->quantite_disponible,                            'reserve' => $stock->quantite_reserve,                        ];                    })                ];            }            return response()->json([                'success' => true,                'data' => [                    'commande' => $commande,                    'stock_disponible' => $stockParSuccursale                ]            ]);        } catch (\Throwable $e) {            Log::error('Erreur show logistique: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 404);        }    }    /**     * =============================================     * ASSIGNATION DES COMMANDES     * =============================================     */    /**     * Récupérer les succursales disponibles pour une commande     */    public function getSuccursalesDisponibles($commandeId)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $commande = CommandeClient::with('lignes.produit')->findOrFail($commandeId);            if (!$commande->peutAssigner) {                return response()->json([                    'success' => false,                    'message' => 'Cette commande ne peut pas être assignée'                ], 422);            }            $succursalesQuery = Succursale::where('est_active', true)                ->where('statut', 'ACTIVE');            // Si chef d'agence, limiter à sa succursale            if ($user->isChefAgence() && $user->succursale_id) {                $succursalesQuery->where('id', $user->succursale_id);            }            $succursales = $succursalesQuery->get()                ->map(function ($succursale) use ($commande) {                    $disponible = true;                    $stockManquant = [];                    $stockDetails = [];                    foreach ($commande->lignes as $ligne) {                        $stock = StockSuccursale::where('succursale_id', $succursale->id)                            ->where('produit_id', $ligne->produit_id)                            ->first();                        $stockDetails[] = [                            'produit' => $ligne->produit->nom,                            'quantite_demandee' => $ligne->quantite,                            'disponible' => $stock ? $stock->quantite_disponible : 0,                            'suffisant' => $stock && $stock->quantite_disponible >= $ligne->quantite                        ];                        if (!$stock || $stock->quantite_disponible < $ligne->quantite) {                            $disponible = false;                            $stockManquant[] = [                                'produit' => $ligne->produit->nom,                                'disponible' => $stock ? $stock->quantite_disponible : 0,                                'demande' => $ligne->quantite,                                'manquant' => $ligne->quantite - ($stock ? $stock->quantite_disponible : 0)                            ];                        }                    }                    // Charge de travail de la succursale                    $charge = CommandeClient::where('succursale_assignee_id', $succursale->id)                        ->whereIn('statut', ['ASSIGNEE', 'EN_PREPARATION', 'PRETE'])                        ->count();                    return [                        'id' => $succursale->id,                        'nom' => $succursale->nom,                        'code' => $succursale->code,                        'ville' => $succursale->ville,                        'adresse' => $succursale->adresse,                        'disponible' => $disponible,                        'charge' => $charge,                        'stock_details' => $stockDetails,                        'stock_manquant' => $stockManquant                    ];                });            return response()->json([                'success' => true,                'data' => [                    'commande' => [                        'id' => $commande->id,                        'reference' => $commande->reference,                        'total' => $commande->total,                    ],                    'succursales' => $succursales                ]            ]);        } catch (\Throwable $e) {            Log::error('Erreur getSuccursalesDisponibles: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 500);        }    }    /**     * Assigner une commande à une succursale     */    public function assigner(Request $request, $commandeId)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $request->validate([                'succursale_id' => 'required|exists:succursales,id',                'notes' => 'nullable|string'            ]);            $commande = CommandeClient::with('lignes.produit')->findOrFail($commandeId);            if (!$commande->peutAssigner) {                return response()->json([                    'success' => false,                    'message' => 'Cette commande ne peut pas être assignée. Statut: ' . $commande->statut                ], 422);            }            // Vérifier les permissions            if ($user->isChefAgence() && $user->succursale_id) {                if ($request->succursale_id != $user->succursale_id) {                    return response()->json([                        'success' => false,                        'message' => 'Vous ne pouvez assigner qu\'à votre succursale.'                    ], 403);                }            }            // Assigner la commande            $this->commandeService->assignerCommande($commande, $succursale->id, $user->id);            // Ajouter des notes si fournies            if ($request->filled('notes')) {                $commande->notes = ($commande->notes ? $commande->notes . "\n" : '')                     . '[LOGISTIQUE] ' . $request->notes . ' - ' . now()->format('d/m/Y H:i') . ' par ' . $user->nom_complet;                $commande->save();            }            return response()->json([                'success' => true,                'message' => 'Commande assignée avec succès à ' . $succursale->nom,                'data' => $commande->fresh([                    'client',                     'lignes.produit',                     'livraison',                     'succursaleAssignee',                     'assignePar'                ])            ]);        } catch (\Throwable $e) {            Log::error('Erreur assigner commande: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 500);        }    }    /**     * =============================================     * SUIVI DES COMMANDES     * =============================================     */    /**     * Suivi d'une commande     */    public function suivi($id)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $commande = CommandeClient::with([                'client',                'lignes.produit',                'livraison',                'succursaleAssignee',                'assignePar'            ])->findOrFail($id);            // Vérifier les permissions            if ($user->isChefAgence() && $user->succursale_id) {                if ($commande->succursale_assignee_id && $commande->succursale_assignee_id != $user->succursale_id) {                    return response()->json([                        'success' => false,                        'message' => 'Vous n\'avez pas accès à cette commande.'                    ], 403);                }            }            // Historique des statuts depuis la livraison            $historique = $commande->livraison?->historique_statuts ?? [];            // Timeline des événements            $timeline = [                [                    'date' => $commande->created_at,                    'statut' => 'COMMANDE_CREEE',                    'label' => 'Commande créée',                    'description' => 'Commande #' . $commande->reference . ' créée par le client'                ]            ];            if ($commande->date_paiement) {                $timeline[] = [                    'date' => $commande->date_paiement,                    'statut' => 'PAIEMENT_VALIDE',                    'label' => 'Paiement validé',                    'description' => 'Paiement confirmé pour un montant de ' . number_format($commande->total, 2) . ' USD'                ];            }            if ($commande->date_assignation) {                $timeline[] = [                    'date' => $commande->date_assignation,                    'statut' => 'COMMANDE_ASSIGNEE',                    'label' => 'Commande assignée',                    'description' => 'Assignée à ' . ($commande->succursaleAssignee?->nom ?? 'N/A')                         . ' par ' . ($commande->assignePar?->nom_complet ?? 'N/A')                ];            }            if ($commande->date_expedition) {                $timeline[] = [                    'date' => $commande->date_expedition,                    'statut' => 'COMMANDE_EXPEDIEE',                    'label' => 'Commande expédiée',                    'description' => 'Commande remise au transporteur'                ];            }            if ($commande->date_livraison) {                $timeline[] = [                    'date' => $commande->date_livraison,                    'statut' => 'COMMANDE_LIVREE',                    'label' => 'Commande livrée',                    'description' => 'Commande livrée avec succès'                ];            }            // Ajouter l'historique de la livraison            foreach ($historique as $item) {                $timeline[] = [                    'date' => $item['date'] ?? now(),                    'statut' => $item['statut'] ?? 'UPDATE',                    'label' => $item['statut'] ?? 'Mise à jour',                    'description' => $item['description'] ?? ''                ];            }            // Trier par date            usort($timeline, function ($a, $b) {                $dateA = is_string($a['date']) ? strtotime($a['date']) : $a['date']->timestamp;                $dateB = is_string($b['date']) ? strtotime($b['date']) : $b['date']->timestamp;                return $dateA - $dateB;            });            return response()->json([                'success' => true,                'data' => [                    'commande' => [                        'id' => $commande->id,                        'reference' => $commande->reference,                        'statut' => $commande->statut,                        'statut_label' => $commande->statut_label,                        'statut_logistique' => $commande->statut_logistique,                        'statut_logistique_label' => $commande->statut_logistique_label,                        'total' => $commande->total,                    ],                    'client' => [                        'id' => $commande->client->id,                        'nom' => $commande->client->nom_complet,                        'email' => $commande->client->email,                        'telephone' => $commande->client->telephone,                    ],                    'succursale' => $commande->succursaleAssignee ? [                        'id' => $commande->succursaleAssignee->id,                        'nom' => $commande->succursaleAssignee->nom,                        'code' => $commande->succursaleAssignee->code,                        'ville' => $commande->succursaleAssignee->ville,                    ] : null,                    'livraison' => $commande->livraison,                    'timeline' => $timeline,                ]            ]);        } catch (\Throwable $e) {            Log::error('Erreur suivi commande: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 500);        }    }    /**     * =============================================     * RAPPORTS     * =============================================     */    /**     * Rapport des commandes     */    public function rapport(Request $request)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $request->validate([                'date_debut' => 'required|date',                'date_fin' => 'required|date|after_or_equal:date_debut',                'succursale_id' => 'nullable|exists:succursales,id'            ]);            $query = CommandeClient::whereBetween('created_at', [                $request->date_debut . ' 00:00:00',                $request->date_fin . ' 23:59:59'            ]);            // Filtrer par succursale si chef d'agence            if ($user->isChefAgence() && $user->succursale_id) {                $query->where('succursale_assignee_id', $user->succursale_id);            }            if ($request->filled('succursale_id')) {                if (!$user->isChefAgence() || $user->succursale_id == $request->succursale_id) {                    $query->where('succursale_assignee_id', $request->succursale_id);                }            }            $commandes = $query->get();            $statutCounts = [];            foreach (CommandeClient::STATUTS as $key => $label) {                $statutCounts[$key] = $commandes->where('statut', $key)->count();            }            return response()->json([                'success' => true,                'data' => [                    'periode' => [                        'debut' => $request->date_debut,                        'fin' => $request->date_fin                    ],                    'total_commandes' => $commandes->count(),                    'montant_total' => $commandes->sum('total'),                    'montant_moyen' => $commandes->count() > 0 ? $commandes->avg('total') : 0,                    'par_statut' => $statutCounts,                    'par_succursale' => $commandes->groupBy('succursale_assignee_id')                        ->map(function ($group) {                            $succursale = $group->first()->succursaleAssignee;                            return [                                'succursale' => $succursale ? $succursale->nom : 'Non assignée',                                'nombre' => $group->count(),                                'montant' => $group->sum('total')                            ];                        })->values()                ]            ]);        } catch (\Throwable $e) {            Log::error('Erreur rapport logistique: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 500);        }    }    /**     * =============================================     * TRANSFERTS DE STOCK     * =============================================     */    /**     * Transférer du stock entre succursales     */    public function transfererStock(Request $request)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $request->validate([                'produit_id' => 'required|exists:produit,id',                'quantite' => 'required|integer|min:1',                'source_succursale_id' => 'required|exists:succursales,id',                'destination_succursale_id' => 'required|exists:succursales,id|different:source_succursale_id',                'motif' => 'nullable|string'            ]);            // Vérifier les permissions            if ($user->isChefAgence() && $user->succursale_id) {                if ($request->source_succursale_id != $user->succursale_id) {                    return response()->json([                        'success' => false,                        'message' => 'Vous ne pouvez transférer que depuis votre succursale.'                    ], 403);                }            }            return DB::transaction(function () use ($request, $user) {                $source = Succursale::findOrFail($request->source_succursale_id);                $destination = Succursale::findOrFail($request->destination_succursale_id);                // Vérifier le stock source                $stockSource = StockSuccursale::where('succursale_id', $source->id)                    ->where('produit_id', $request->produit_id)                    ->lockForUpdate()                    ->first();                if (!$stockSource || $stockSource->quantite_disponible < $request->quantite) {                    $disponible = $stockSource ? $stockSource->quantite_disponible : 0;                    throw new \Exception("Stock insuffisant dans {$source->nom}. Disponible: {$disponible}, Demandé: {$request->quantite}");                }                // Créer ou mettre à jour le stock destination                $stockDestination = StockSuccursale::where('succursale_id', $destination->id)                    ->where('produit_id', $request->produit_id)                    ->first();                if (!$stockDestination) {                    $produit = Produit::find($request->produit_id);                    $stockDestination = StockSuccursale::create([                        'succursale_id' => $destination->id,                        'produit_id' => $request->produit_id,                        'quantite_disponible' => 0,                        'quantite_reserve' => 0,                        'quantite_minimale' => $produit->stock_minimum ?? 5,                        'is_depot' => false,                        'emplacement' => 'Transfert automatique'                    ]);                }                // Effectuer le transfert                $stockSource->quantite_disponible -= $request->quantite;                $stockSource->save();                $stockDestination->quantite_disponible += $request->quantite;                $stockDestination->save();                // Journaliser le mouvement                MouvementStock::create([                    'reference_mouvement' => 'TRF-' . now()->format('Ymd') . '-' . uniqid(),                    'succursale_id' => $source->id,                    'produit_id' => $request->produit_id,                    'stock_source_id' => $stockSource->id,                    'stock_destination_id' => $stockDestination->id,                    'type_mouvement' => 'TRANSFERT',                    'statut' => 'VALIDE',                    'quantite' => $request->quantite,                    'quantite_avant' => $stockSource->quantite_disponible + $request->quantite,                    'quantite_apres' => $stockSource->quantite_disponible,                    'raison' => $request->motif ?? 'Transfert logistique',                    'responsable_id' => $user->id,                    'valide_par_id' => $user->id,                    'date_validation' => now(),                    'date_mouvement' => now(),                ]);                return response()->json([                    'success' => true,                    'message' => 'Stock transféré avec succès',                    'data' => [                        'source' => [                            'succursale' => $source->nom,                            'quantite_restante' => $stockSource->quantite_disponible,                        ],                        'destination' => [                            'succursale' => $destination->nom,                            'quantite_actuelle' => $stockDestination->quantite_disponible,                        ],                        'quantite_transferee' => $request->quantite,                        'produit_id' => $request->produit_id,                        'transfere_par' => $user->nom_complet,                    ]                ]);            });        } catch (\Throwable $e) {            Log::error('Erreur transfert stock: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 500);        }    }    /**     * =============================================     * STATISTIQUES AVANCÉES     * =============================================     */    /**     * Statistiques avancées pour le logisticien     */    public function statistiquesAvancees(Request $request)    {        try {            $user = auth()->user();            if (!$user) {                return response()->json([                    'success' => false,                    'message' => 'Utilisateur non authentifié.'                ], 401);            }            $query = CommandeClient::query();            if ($user->isChefAgence() && $user->succursale_id) {                $query->where('succursale_assignee_id', $user->succursale_id);            }            // Temps moyen de traitement            $commandesTerminees = (clone $query)                ->whereIn('statut', ['LIVREE', 'ANNULEE'])                ->whereNotNull('date_assignation')                ->get();            $tempsMoyen = 0;            if ($commandesTerminees->count() > 0) {                $totalMinutes = 0;                foreach ($commandesTerminees as $commande) {                    if ($commande->statut === 'LIVREE' && $commande->date_livraison) {                        $minutes = $commande->date_livraison->diffInMinutes($commande->date_assignation);                        $totalMinutes += $minutes;                    }                }                $tempsMoyen = $totalMinutes / $commandesTerminees->count();            }            // Performance par succursale            $succursalesQuery = Succursale::where('est_active', true);                        if ($user->isChefAgence() && $user->succursale_id) {                $succursalesQuery->where('id', $user->succursale_id);            }            $performanceSuccursale = $succursalesQuery->get()                ->map(function ($succursale) {                    $commandes = CommandeClient::where('succursale_assignee_id', $succursale->id)                        ->whereIn('statut', ['LIVREE', 'ANNULEE'])                        ->get();                    $livrees = $commandes->where('statut', 'LIVREE')->count();                    $total = $commandes->count();                    return [                        'succursale' => $succursale->nom,                        'total_traitees' => $total,                        'livrees' => $livrees,                        'taux_succes' => $total > 0 ? round(($livrees / $total) * 100, 2) : 0,                    ];                });            return response()->json([                'success' => true,                'data' => [                    'temps_moyen_traitement_minutes' => round($tempsMoyen, 2),                    'commandes_en_attente' => CommandeClient::enAttenteAssignation()                        ->when($user->isChefAgence() && $user->succursale_id, function ($q) use ($user) {                            return $q->where('succursale_assignee_id', $user->succursale_id);                        })                        ->count(),                    'taux_assignation' => [                        'assignees' => (clone $query)->whereNotNull('succursale_assignee_id')->count(),                        'total_payees' => (clone $query)->where('statut', '!=', 'EN_ATTENTE_PAIEMENT')->count(),                    ],                    'performance_succursales' => $performanceSuccursale,                    'user' => [                        'id' => $user->id,                        'nom' => $user->nom_complet,                        'role' => $user->role?->nom_role,                        'succursale' => $user->succursale?->nom,                    ]                ]            ]);        } catch (\Throwable $e) {            Log::error('Erreur statistiques avancées: ' . $e->getMessage());            return response()->json([                'success' => false,                'message' => $e->getMessage()            ], 500);        }    }}